using System.Text;
using OpenApiSentinel.Core;

namespace OpenApiSentinel.Reporting;

/// <summary>Single-file, offline HTML report. Aggregation is presentation-only.</summary>
public sealed class HtmlReporter : IResultReporter
{
    public string FormatName => "html";

    public string Render(ComparisonResult result, ReporterOptions options)
    {
        var m = HtmlPresentation.Build(result); var l = new HtmlLocalizer(options.HtmlLanguage); var w = new StringBuilder(64 * 1024); var passed = !result.PolicyViolated;
        w.AppendLine("<!DOCTYPE html>"); w.AppendLine($"<html lang=\"{(l.IsChinese ? "zh-Hant-TW" : "en")}\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">");
        w.AppendLine($"<title>OpenAPI Sentinel — {E(result.OldContractName)} → {E(result.NewContractName)}</title>{Styles}</head><body><header class=\"topbar\"><div class=\"wrap brand\">🛡 <b>OpenAPI Sentinel</b><span>{E(l.T("API 相容性報告", "API Compatibility Report"))}</span><strong class=\"verdict {(passed ? "pass" : "fail") }\">{E(passed ? l.T("通過", "PASSED") : l.T("未通過", "FAILED"))}</strong></div></header><main class=\"wrap\">");
        Header(w, result, passed, l); Snapshot(w, options, l); Summary(w, result, m, l);
        if (m.Attention.Count > 0) FindingSection(w, l.T("需要處理", "Needs attention"), m.Attention, l, true, "attention");
        Endpoints(w, m.Endpoints, l); Related(w, m.Related, l); Details(w, m, l);
        if (options.IncludeSuppressed && result.Suppressed.Count > 0) w.AppendLine($"<section class=\"card\"><h2>{E(l.T("已抑制的 Findings", "Suppressed findings"))} ({result.Suppressed.Count})</h2><ul>{string.Join("", result.Suppressed.Select(x => $"<li>{E(x.Finding.RuleId)} · {E(x.Reason)}</li>"))}</ul></section>");
        w.AppendLine($"<footer>{E(l.T("由 OpenAPI Sentinel 產生。離線、可重現的合約分析。", "Generated by OpenAPI Sentinel — deterministic, offline contract analysis."))}</footer></main>{Script}</body></html>"); return w.ToString();
    }

    private static void Header(StringBuilder w, ComparisonResult r, bool passed, HtmlLocalizer l)
    {
        w.AppendLine("<section class=\"card\"><div class=\"head\">"); Cell(w, l.T("結果", "Result"), $"<span class=\"badge {(passed ? "ok" : "bad")}\">{E(passed ? l.T("通過", "PASSED") : l.T("未通過", "FAILED"))}</span>");
        Cell(w, l.T("舊版合約", "Old contract"), $"<span class=\"mono\">{E(r.OldContractName)}</span><small>{Spec(r.OldOpenApiVersion, r.OldInfoVersion, l)}</small>"); Cell(w, l.T("新版合約", "New contract"), $"<span class=\"mono\">{E(r.NewContractName)}</span><small>{Spec(r.NewOpenApiVersion, r.NewInfoVersion, l)}</small>");
        Cell(w, l.T("產生時間（UTC）", "Generated (UTC)"), $"{r.GeneratedAtUtc:yyyy-MM-dd HH:mm:ss}<small>tool {E(r.ToolVersion)} · schema {E(r.SchemaVersion)}</small>"); w.AppendLine("</div>"); if (r.Recommendation is { } rec) w.AppendLine($"<p class=\"rec\"><b>{E(l.T("版本建議", "Recommended version bump"))}: {E(rec.Display)}</b> · {E(rec.Reason)}</p>"); w.AppendLine("</section>");
    }
    private static void Cell(StringBuilder w, string label, string value) => w.AppendLine($"<div><div class=\"lbl\">{E(label)}</div><div class=\"val\">{value}</div></div>");
    private static string Spec(string? spec, string? api, HtmlLocalizer l) { var a = new List<string>(); if (!string.IsNullOrEmpty(spec)) a.Add("spec " + spec); if (!string.IsNullOrEmpty(api)) a.Add(l.T("API 版本 ", "API ") + (api.StartsWith('v') || api.StartsWith('V') ? api : "v" + api)); return E(string.Join(" · ", a)); }
    private static void Snapshot(StringBuilder w, ReporterOptions o, HtmlLocalizer l)
    {
        var (state, text, cls) = o.SnapshotStatus switch { HtmlSnapshotStatus.Pending => (l.T("等待更新", "Pending update"), l.T("所有報表已成功產生；比較通過後才會原子更新 Snapshot。", "Reports succeeded; the snapshot advances only after policy passes."), "pending"), HtmlSnapshotStatus.PolicyFailed => (l.T("未更新", "Not updated"), l.T("原因：比較未通過 Policy，本機 Snapshot 保留舊版本。", "Reason: the comparison did not pass policy; the local snapshot remains unchanged."), "bad"), HtmlSnapshotStatus.Updated => (l.T("已更新", "Updated"), l.T("下一次比較將以此次版本作為 OLD Snapshot。", "The next comparison will use this version as the OLD snapshot."), "ok"), _ => (l.T("未啟用", "Not enabled"), l.T("本次比較不會修改 OLD contract。", "This comparison will not modify the OLD contract."), "") };
        w.AppendLine($"<section class=\"card snapshot {cls}\"><h2>{E(l.T("Snapshot 狀態", "Snapshot status"))}</h2><b>{E(state)}</b><p>{E(text)}</p>"); if (o.SnapshotStatus == HtmlSnapshotStatus.Updated) w.AppendLine($"<small>{E(l.T("位置", "Path"))}: {E(o.SnapshotPath)}<br>{E(l.T("來源", "Source"))}: {E(o.SnapshotSource)}</small>"); w.AppendLine("</section>");
    }
    private static void Summary(StringBuilder w, ComparisonResult r, HtmlReportModel m, HtmlLocalizer l)
    {
        var breaking = m.Findings.Count(x => x.Finding.Compatibility == Compatibility.Breaking); var review = m.Findings.Count(x => HtmlPresentation.IsAttention(x.Finding) && x.Finding.Compatibility != Compatibility.Breaking); var safe = m.Findings.Count - breaking - review; var added = m.Endpoints.Count(x => x.Endpoint.State == EndpointState.Added); var removed = m.Endpoints.Count(x => x.Endpoint.State == EndpointState.Removed); var changed = m.Endpoints.Count(x => x.Endpoint.State == EndpointState.Changed);
        w.AppendLine($"<section class=\"card summary\"><h2>{E(l.T("本次變更摘要", "Change summary"))}</h2><div class=\"summary\"><b>🔴 {E(l.T("需要立即處理", "Needs attention"))}: {breaking}</b><b>🟠 {E(l.T("建議確認", "Needs review"))}: {review}</b><b>🟢 {E(l.T("一般變更", "General changes"))}: {safe}</b></div><p>Endpoint: + {added} · − {removed} · ~ {changed}</p><small>{E(l.T("原始規則事件", "Raw rule events"))} {r.Findings.Count} · {E(l.T("獨立變更", "Distinct changes"))} {m.Findings.Count} · {E(l.T("已合併重複", "Duplicates collapsed"))} {r.Findings.Count - m.Findings.Count}</small></section>");
    }
    private static void Endpoints(StringBuilder w, IReadOnlyList<HtmlEndpoint> es, HtmlLocalizer l)
    {
        if (es.Count == 0) return; w.AppendLine($"<section class=\"card\"><h2>{E(l.T("受影響的 Endpoint", "Affected endpoints"))}</h2><div class=\"scroll\"><table><thead><tr><th>{E(l.T("狀態", "State"))}</th><th>Endpoint</th><th>{E(l.T("具體變更", "Concrete changes"))}</th><th>{E(l.T("風險", "Risk"))}</th></tr></thead><tbody>");
        foreach (var e in es) { var text = e.Findings.Count == 0 ? e.Endpoint.State switch { EndpointState.Added => l.T("新增 Endpoint", "Endpoint added"), EndpointState.Removed => l.T("Endpoint 已移除", "Endpoint removed"), _ => "—" } : string.Join("；", e.Findings.Take(3).Select(x => l.Short(x.Finding))); var risk = e.Findings.Any(x => x.Finding.Compatibility == Compatibility.Breaking) ? l.T("高風險", "High risk") : e.Findings.Any(x => HtmlPresentation.IsAttention(x.Finding)) ? l.T("需確認", "Review") : l.T("一般", "Normal"); w.AppendLine($"<tr><td><span class=\"state\">{E(l.State(e.Endpoint.State))}</span></td><td class=\"mono\">{E(Name(e.Endpoint.Path, e.Endpoint.HttpMethod))}</td><td>{E(text)} <small>({e.Findings.Count} {E(l.T("個獨立變更", "distinct"))})</small></td><td>{E(risk)}</td></tr>"); }
        w.AppendLine("</tbody></table></div></section>");
    }
    private static void Related(StringBuilder w, IReadOnlyList<HtmlRelatedChange> gs, HtmlLocalizer l)
    {
        if (gs.Count == 0) return; w.AppendLine($"<section class=\"card\"><h2>{E(l.T("相關變更", "Related changes"))}</h2>"); foreach (var g in gs) w.AppendLine($"<details><summary><b class=\"mono\">{E(Name(g.Path, g.Method))}</b> · {E(g.ParentLocation)} · {g.Findings.Count} {E(l.T("個相關變更", "related changes"))}</summary><ul>{string.Join("", g.Findings.Select(x => $"<li>{E(l.Short(x.Finding))}</li>"))}</ul></details>"); w.AppendLine("</section>");
    }
    private static void Details(StringBuilder w, HtmlReportModel m, HtmlLocalizer l)
    {
        w.AppendLine($"<section class=\"card\"><h2>{E(l.T("詳細變更", "Detailed changes"))}</h2><div class=\"filters\"><input id=\"search\" type=\"search\" placeholder=\"{E(l.T("搜尋路徑、規則或變更內容…", "Search path, rule, explanation…"))}\"><select id=\"f-compat\"><option value=\"\">{E(l.T("所有相容性", "All compatibility"))}</option><option>Breaking</option><option>PotentiallyBreaking</option><option>NonBreaking</option><option>Informational</option><option>Unknown</option></select><label><input id=\"f-breaking-only\" type=\"checkbox\"> {E(l.T("只看需要處理", "Needs attention only"))}</label><button type=\"button\" id=\"expand\">{E(l.T("全部展開", "Expand all"))}</button><button type=\"button\" id=\"collapse\">{E(l.T("全部收合", "Collapse all"))}</button></div><p id=\"visible-count\" data-template=\"{E(l.T("顯示 {0} 個變更", "Showing {0} changes"))}\"></p><div id=\"findings\">");
        foreach (var f in m.Attention) Card(w, f, l, true); w.AppendLine($"<details class=\"other\"><summary><b>{E(l.T("其他變更（Non-breaking / Informational）", "Other changes (Non-breaking / Informational)"))} ({m.Other.Count})</b></summary>"); foreach (var f in m.Other) Card(w, f, l, false); w.AppendLine("</details></div></section>");
    }
    private static void FindingSection(StringBuilder w, string title, IReadOnlyList<HtmlFinding> fs, HtmlLocalizer l, bool open, string cls) { w.AppendLine($"<section class=\"card {cls}\"><h2>{E(title)} ({fs.Count})</h2>"); foreach (var f in fs) Card(w, f, l, open); w.AppendLine("</section>"); }
    private static void Card(StringBuilder w, HtmlFinding i, HtmlLocalizer l, bool open)
    {
        var f = i.Finding; var text = E($"{f.Path} {f.Location} {f.RuleId} {f.Title} {l.Title(f)} {l.Explanation(f)}".ToLowerInvariant()); w.AppendLine($"<details class=\"finding\" {(open ? "open" : "")} data-compat=\"{f.Compatibility}\" data-attention=\"{HtmlPresentation.IsAttention(f).ToString().ToLowerInvariant()}\" data-text=\"{text}\"><summary><span class=\"severity\">{E(f.Severity.ToString().ToUpperInvariant())}</span><span class=\"mono\">{E(Name(f.Path, f.HttpMethod))}</span><span>{E(l.Short(f))}</span><span class=\"compat\">{E(l.CompatibilityLabel(f.Compatibility))}</span></summary><div class=\"body\"><p><b>{E(l.Title(f))}</b> <small>· {E(f.RuleId)} · {E(f.ChangeType.ToString())}</small></p><p>{E(l.Explanation(f))}</p>");
        if (f.OldValue is not null || f.NewValue is not null) w.AppendLine($"<div class=\"values\"><div><span class=\"lbl\">{E(l.T("更新前", "Before"))}</span><pre>{E(f.OldValue ?? "(none)")}</pre></div><div><span class=\"lbl\">{E(l.T("更新後", "After"))}</span><pre>{E(f.NewValue ?? "(removed)")}</pre></div></div>");
        w.AppendLine($"<div class=\"grid\"><div><span class=\"lbl\">{E(l.T("影響", "Impact"))}</span><p>{E(l.Impact(f))}</p></div><div><span class=\"lbl\">{E(l.T("建議處理方式", "Suggested action"))}</span><p>{E(l.Action(f))}</p></div></div>"); if (i.DuplicateCount > 1) w.AppendLine($"<small>{E(l.T("已合併", "Merged"))} {i.DuplicateCount} {E(l.T("筆相同規則事件", "identical rule events"))}</small>"); w.AppendLine("</div></details>");
    }
    private static string Name(string path, HttpMethodKind method) => string.IsNullOrEmpty(method.ToHttpString()) ? path : method.ToHttpString() + " " + path;
    private static string E(string? value) => (value ?? "").Replace("&", "&amp;", StringComparison.Ordinal).Replace("<", "&lt;", StringComparison.Ordinal).Replace(">", "&gt;", StringComparison.Ordinal).Replace("\"", "&quot;", StringComparison.Ordinal).Replace("'", "&#39;", StringComparison.Ordinal);
    private const string Styles = """
<style>:root{--bg:#f6f8fa;--card:#fff;--ink:#1f2328;--muted:#656d76;--line:#d8dee4;--red:#cf222e;--orange:#bc4c00;--green:#1a7f37}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:1240px;margin:auto;padding:0 20px}.topbar{background:#10151c;color:#fff;padding:14px 0}.brand{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.brand span,small,.lbl,footer{color:var(--muted);font-size:12px}.verdict{margin-left:auto;padding:4px 12px;border-radius:999px}.pass,.ok{color:var(--green);background:#dafbe1}.fail,.bad{color:var(--red);background:#ffebe9}main{display:grid;gap:16px;padding-top:22px;padding-bottom:35px}.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:17px}.head,.summary,.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}.lbl{text-transform:uppercase;letter-spacing:.5px}.val{font-weight:600;word-break:break-word}.badge,.state,.severity,.compat{padding:3px 9px;border-radius:999px;font-weight:700;font-size:12px}.rec{border-top:1px dashed var(--line);padding-top:10px}.snapshot.pending{border-color:var(--orange)}.summary{border-left:4px solid #0969da}.attention{border-left:4px solid var(--red)}h2{font-size:18px;margin:0 0 12px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:8px;border-bottom:1px solid var(--line);vertical-align:top}tr:hover{background:#f6f8fa}.mono,pre{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;word-break:break-word}details{border:1px solid var(--line);border-radius:8px;margin:8px 0;background:#fff}summary{cursor:pointer;padding:10px;display:flex;gap:9px;align-items:center;flex-wrap:wrap}.finding summary .compat{margin-left:auto;background:#eaeef2}.body{border-top:1px solid var(--line);padding:10px 14px}.body p{margin:6px 0}.values{display:grid;grid-template-columns:1fr 1fr;gap:12px}.values pre{white-space:pre-wrap;background:var(--bg);padding:8px;margin:4px 0}.filters{display:flex;gap:8px;flex-wrap:wrap;position:sticky;top:0;background:var(--card);padding:6px 0}input,select,button{font:inherit;padding:7px 9px;border:1px solid var(--line);border-radius:7px;background:#fff}input{flex:1 1 260px}footer{text-align:center}@media(max-width:650px){.wrap{padding:0 12px}.values{grid-template-columns:1fr}.brand{align-items:flex-start}.finding summary .compat{margin-left:0}}@media print{.topbar{background:#fff;color:#000}.filters,button{display:none}.other{display:block}details{break-inside:avoid}}</style>
""";
    private const string Script = """
<script>(()=>{const q=document.querySelector('#search'),c=document.querySelector('#f-compat'),b=document.querySelector('#f-breaking-only'),cards=[...document.querySelectorAll('.finding')],count=document.querySelector('#visible-count');function apply(){let n=0;cards.forEach(x=>{const ok=(!q.value||x.dataset.text.includes(q.value.toLowerCase()))&&(!c.value||x.dataset.compat===c.value)&&(!b.checked||x.dataset.attention==='true');x.hidden=!ok;if(ok)n++});count.textContent=count.dataset.template.replace('{0}',n);if(q.value||c.value||b.checked)document.querySelector('.other').open=true}q?.addEventListener('input',apply);c?.addEventListener('change',apply);b?.addEventListener('change',apply);document.querySelector('#expand')?.addEventListener('click',()=>document.querySelectorAll('details').forEach(x=>x.open=true));document.querySelector('#collapse')?.addEventListener('click',()=>document.querySelectorAll('details').forEach(x=>x.open=false));apply()})()</script>
""";
}
